#!/usr/bin/env bash
# nats TLS: install the listeners' certificate and key generated by OpenTofu
# (tls_self_signed_cert.nats in proxmox/opentofu/nats.tf: the hub's name and
# IP, so clients can pin it). Run by terraform_data.nats_tls after setup.sh.
#
# stdin: the certificate PEM, then the private key PEM. The key never touches
# argv or the repo. The server restarts only when the pair changed.
set -euo pipefail

d=/etc/nats/tls
in=$(cat)
cert=$(printf '%s\n' "$in" | sed -n '/-----BEGIN CERTIFICATE-----/,/-----END CERTIFICATE-----/p')
key=$(printf '%s\n' "$in" | sed -n '/-----BEGIN [A-Z ]*PRIVATE KEY-----/,/-----END [A-Z ]*PRIVATE KEY-----/p')
[ -n "$cert" ] && [ -n "$key" ] || { echo "expected a certificate and a private key on stdin" >&2; exit 1; }

umask 027
install -d -o root -g nats -m 0750 "$d"
printf '%s\n' "$cert" > "$d/.cert.new"
printf '%s\n' "$key" > "$d/.key.new"
# the pair must match before it replaces the running one
[ "$(openssl x509 -in "$d/.cert.new" -noout -pubkey)" = "$(openssl pkey -in "$d/.key.new" -pubout)" ] ||
  { rm -f "$d/.cert.new" "$d/.key.new"; echo "certificate and key do not match" >&2; exit 1; }
chown root:nats "$d/.cert.new" "$d/.key.new"
chmod 0644 "$d/.cert.new"
chmod 0640 "$d/.key.new"

if cmp -s "$d/.cert.new" "$d/cert.pem" && cmp -s "$d/.key.new" "$d/key.pem"; then
  rm -f "$d/.cert.new" "$d/.key.new"
  echo "nats tls: unchanged"
  exit 0
fi
mv "$d/.cert.new" "$d/cert.pem"
mv "$d/.key.new" "$d/key.pem"
systemctl restart nats
ip=$(sed -n 's/^http: \(.*\):8222$/\1/p' /etc/nats/nats.conf)
for _ in $(seq 1 30); do
  curl -fsS "http://${ip}:8222/healthz?js-enabled-only=true" >/dev/null 2>&1 && break
  sleep 1
done
curl -fsS "http://${ip}:8222/healthz?js-enabled-only=true" >/dev/null
echo "nats tls: installed $(openssl x509 -in "$d/cert.pem" -noout -subject -enddate | tr '\n' ' ')"
